-- DIHASILKAN OTOMATIS oleh scripts/build-seed.mjs — jangan diedit manual.
-- Sumber: supabase/seed/data.mjs
-- Aman diulang: kategori di-upsert, soal dengan seed_key yang sudah ada dilewati.
do $seed$
declare
  g jsonb; c jsonb; q jsonb;
  v_parent uuid; v_q uuid; v_correct uuid;
  i integer; v_added integer := 0;
begin
  for g in select * from jsonb_array_elements($j$[{"arena":"mufrodat","slug":"mufrodat-kosakata","name":"Kosakata","name_ar":"الْمُفْرَدَاتُ","sort":0,"children":[{"slug":"dasar","name":"Kosakata dasar","name_ar":"مُفْرَدَاتٌ أَسَاسِيَّةٌ","sort":0},{"slug":"sekolah","name":"Sekolah dan kelas","name_ar":"الْمَدْرَسَةُ وَالْفَصْلُ","sort":1},{"slug":"rumah","name":"Rumah dan keluarga","name_ar":"الْبَيْتُ وَالْأُسْرَةُ","sort":2},{"slug":"makanan","name":"Makanan dan minuman","name_ar":"الطَّعَامُ وَالشَّرَابُ","sort":3},{"slug":"aktivitas","name":"Aktivitas sehari-hari","name_ar":"الْأَنْشِطَةُ الْيَوْمِيَّةُ","sort":4},{"slug":"perjalanan","name":"Perjalanan","name_ar":"السَّفَرُ","sort":5},{"slug":"kampus","name":"Kampus","name_ar":"الْجَامِعَةُ","sort":6}]},{"arena":"mufrodat","slug":"mufrodat-percakapan","name":"Ungkapan & Percakapan","name_ar":"الْمُحَادَثَةُ","sort":1,"children":[{"slug":"salam","name":"Perkenalan dan salam","name_ar":"التَّعَارُفُ وَالتَّحِيَّةُ","sort":0},{"slug":"pasar","name":"Pasar dan restoran","name_ar":"السُّوقُ وَالْمَطْعَمُ","sort":1},{"slug":"ungkapan","name":"Ungkapan sehari-hari","name_ar":"تَعْبِيرَاتٌ يَوْمِيَّةٌ","sort":2},{"slug":"fusha","name":"Percakapan Fusha","name_ar":"مُحَادَثَةٌ بِالْفُصْحَى","sort":3},{"slug":"amiyah","name":"Percakapan Amiyah Mesir","name_ar":"مُحَادَثَةٌ بِالْعَامِّيَّةِ الْمِصْرِيَّةِ","sort":4}]},{"arena":"qowaid","slug":"qowaid-nahwu","name":"Nahwu","name_ar":"النَّحْوُ","sort":2,"children":[{"slug":"mubtada-khabar","name":"Mubtada' & Khabar","name_ar":"الْمُبْتَدَأُ وَالْخَبَرُ","sort":0},{"slug":"fail","name":"Fa'il","name_ar":"الْفَاعِلُ","sort":1},{"slug":"maful-bih","name":"Maf'ul bih","name_ar":"الْمَفْعُولُ بِهِ","sort":2},{"slug":"naat","name":"Na'at","name_ar":"النَّعْتُ","sort":3},{"slug":"idhafah","name":"Idhafah","name_ar":"الْإِضَافَةُ","sort":4},{"slug":"hal","name":"Hal","name_ar":"الْحَالُ","sort":5},{"slug":"tamyiz","name":"Tamyiz","name_ar":"التَّمْيِيزُ","sort":6},{"slug":"nawasikh","name":"Nawasikh","name_ar":"النَّوَاسِخُ","sort":7},{"slug":"majrurat","name":"Majrurat","name_ar":"الْمَجْرُورَاتُ","sort":8},{"slug":"tawabi","name":"Tawabi'","name_ar":"التَّوَابِعُ","sort":9},{"slug":"anwa-jumal","name":"Macam-macam jumlah","name_ar":"أَنْوَاعُ الْجُمَلِ","sort":10}]},{"arena":"qowaid","slug":"qowaid-shorof","name":"Shorof","name_ar":"الصَّرْفُ","sort":3,"children":[{"slug":"madhi","name":"Fi'il Madhi","name_ar":"الْفِعْلُ الْمَاضِي","sort":0},{"slug":"mudhari","name":"Fi'il Mudhari'","name_ar":"الْفِعْلُ الْمُضَارِعُ","sort":1},{"slug":"amr","name":"Fi'il Amr","name_ar":"فِعْلُ الْأَمْرِ","sort":2},{"slug":"mashdar","name":"Mashdar","name_ar":"الْمَصْدَرُ","sort":3},{"slug":"isim-fail","name":"Isim Fa'il","name_ar":"اسْمُ الْفَاعِلِ","sort":4},{"slug":"isim-maful","name":"Isim Maf'ul","name_ar":"اسْمُ الْمَفْعُولِ","sort":5},{"slug":"tashrif","name":"Tashrif al-Af'al","name_ar":"تَصْرِيفُ الْأَفْعَالِ","sort":6},{"slug":"mizan","name":"Mizan Sharfi","name_ar":"الْمِيزَانُ الصَّرْفِيُّ","sort":7},{"slug":"mujarrad-mazid","name":"Mujarrad & Mazid","name_ar":"الْمُجَرَّدُ وَالْمَزِيدُ","sort":8},{"slug":"shahih-mutal","name":"Shahih & Mu'tal","name_ar":"الصَّحِيحُ وَالْمُعْتَلُّ","sort":9}]},{"arena":"qowaid","slug":"qowaid-irab","name":"I'rab","name_ar":"الْإِعْرَابُ","sort":4,"children":[{"slug":"rafa","name":"Rafa'","name_ar":"الرَّفْعُ","sort":0},{"slug":"nashab","name":"Nashab","name_ar":"النَّصْبُ","sort":1},{"slug":"jarr","name":"Jarr","name_ar":"الْجَرُّ","sort":2},{"slug":"jazm","name":"Jazm","name_ar":"الْجَزْمُ","sort":3},{"slug":"alamat-irab","name":"Tanda i'rab asli & cabang","name_ar":"عَلَامَاتُ الْإِعْرَابِ الْأَصْلِيَّةُ وَالْفَرْعِيَّةُ","sort":4},{"slug":"irab-jumlah","name":"I'rab kata dalam kalimat","name_ar":"إِعْرَابُ الْكَلِمَاتِ دَاخِلَ الْجُمَلِ","sort":5}]}]$j$::jsonb) loop
    insert into categories (arena, slug, name, name_ar, sort_order)
    values ((g->>'arena')::arena_type, g->>'slug', g->>'name', g->>'name_ar', (g->>'sort')::int)
    on conflict (slug) do update set name = excluded.name, name_ar = excluded.name_ar, sort_order = excluded.sort_order
    returning id into v_parent;
    for c in select * from jsonb_array_elements(g->'children') loop
      insert into categories (arena, parent_id, slug, name, name_ar, sort_order)
      values ((g->>'arena')::arena_type, v_parent, c->>'slug', c->>'name', c->>'name_ar', (c->>'sort')::int)
      on conflict (slug) do update set parent_id = excluded.parent_id, name = excluded.name,
        name_ar = excluded.name_ar, sort_order = excluded.sort_order;
    end loop;
  end loop;

  for q in select * from jsonb_array_elements($j$[{"key":"b5f630c4622e5a108cf6af33c0f6fe7e","cat":"dasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"بَابٌ","explanation":"بَابٌ artinya pintu. Bentuk jamaknya أَبْوَابٌ.","time":20,"options":["Pintu","Jendela","Dinding","Lantai"],"correct":1,"accepted":[]},{"key":"0931093249dc129d94bd63eed8151813","cat":"dasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"نَافِذَةٌ","explanation":"نَافِذَةٌ artinya jendela. Bentuk jamaknya نَوَافِذُ.","time":20,"options":["Jendela","Pintu","Atap","Kursi"],"correct":1,"accepted":[]},{"key":"efd5688a0aa9b3c084c066e6580e144a","cat":"dasar","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? شَمْسٌ artinya \"bulan\".","ar":"شَمْسٌ","explanation":"Salah. شَمْسٌ artinya matahari, sedangkan bulan adalah قَمَرٌ.","time":20,"options":["Benar","Salah"],"correct":2,"accepted":[]},{"key":"f3b915e2b05f4a35bf51644ab233497b","cat":"dasar","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"air\"?","ar":null,"explanation":"مَاءٌ = air. Pilihan lain: نَارٌ = api, هَوَاءٌ = udara, تُرَابٌ = tanah/debu.","time":20,"options":["مَاءٌ","نَارٌ","هَوَاءٌ","تُرَابٌ"],"correct":1,"accepted":[]},{"key":"7fa4bcdd92f66c1ce4a850983bfcfeab","cat":"dasar","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa lawan kata (ضِدّ) dari kata berikut?","ar":"قَرِيبٌ","explanation":"قَرِيبٌ (dekat) lawannya بَعِيدٌ (jauh). كَبِيرٌ = besar, طَوِيلٌ = panjang/tinggi, سَرِيعٌ = cepat.","time":25,"options":["بَعِيدٌ","كَبِيرٌ","طَوِيلٌ","سَرِيعٌ"],"correct":1,"accepted":[]},{"key":"dab34dd2f14fbc14e32c37302297b7a9","cat":"dasar","type":"vocabulary_challenge","level":"advanced","variety":"fusha","prompt":"Apa bentuk jamak dari kata berikut?","ar":"كِتَابٌ","explanation":"Jamak كِتَابٌ adalah كُتُبٌ (jamak taksir). كِتَابَاتٌ jamak dari كِتَابَةٌ (tulisan), كَتَبَةٌ jamak dari كَاتِبٌ (penulis), مَكَاتِبُ jamak dari مَكْتَبٌ (meja/kantor).","time":30,"options":["كُتُبٌ","كِتَابَاتٌ","كَتَبَةٌ","مَكَاتِبُ"],"correct":1,"accepted":[]},{"key":"7c9637dfec821b155b3f1af434eb386a","cat":"sekolah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"سَبُّورَةٌ","explanation":"سَبُّورَةٌ artinya papan tulis.","time":20,"options":["Papan tulis","Buku tulis","Penghapus","Tas"],"correct":1,"accepted":[]},{"key":"7509d97b301e517496d6fb506cf35172","cat":"sekolah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مُدَرِّسٌ","explanation":"مُدَرِّسٌ adalah isim fa'il dari دَرَّسَ (mengajar), artinya pengajar/guru. Murid = طَالِبٌ atau تِلْمِيذٌ.","time":20,"options":["Guru","Murid","Kepala sekolah","Penjaga sekolah"],"correct":1,"accepted":[]},{"key":"278d68d03f0736ad823c34bf274347e0","cat":"sekolah","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"buku tulis\"?","ar":null,"explanation":"كُرَّاسَةٌ = buku tulis. كِتَابٌ = buku (bacaan), مِمْسَحَةٌ = penghapus, مِسْطَرَةٌ = penggaris.","time":20,"options":["كُرَّاسَةٌ","كِتَابٌ","مِمْسَحَةٌ","مِسْطَرَةٌ"],"correct":1,"accepted":[]},{"key":"4564eb949c8802eaa05612dfc15ab05b","cat":"sekolah","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Kamu ingin meminjam pena temanmu. Kalimat yang tepat adalah …","ar":null,"explanation":"أَسْتَعِيرُ = saya meminjam; هَلْ يُمْكِنُ أَنْ ... = bolehkah .... Pilihan lain berarti: \"Di mana penamu?\", \"Ini penaku.\", \"Aku membeli pena.\"","time":25,"options":["هَلْ يُمْكِنُ أَنْ أَسْتَعِيرَ قَلَمَكَ؟","أَيْنَ قَلَمُكَ؟","هَذَا قَلَمِي.","اِشْتَرَيْتُ قَلَمًا."],"correct":1,"accepted":[]},{"key":"90f3c136ee133fe09eaf34a78f31d627","cat":"rumah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مَطْبَخٌ","explanation":"مَطْبَخٌ berwazan مَفْعَلٌ (isim makan) dari طَبَخَ (memasak): tempat memasak = dapur.","time":20,"options":["Dapur","Kamar tidur","Kamar mandi","Ruang tamu"],"correct":1,"accepted":[]},{"key":"b07de8cddd4fd81db349b9f419270a7a","cat":"rumah","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"جَدَّةٌ","explanation":"جَدَّةٌ = nenek, جَدٌّ = kakek. Ibu = أُمٌّ, bibi = عَمَّةٌ (saudari ayah) atau خَالَةٌ (saudari ibu).","time":20,"options":["Nenek","Bibi","Kakek","Ibu"],"correct":1,"accepted":[]},{"key":"c13cbb77e4d593d56bf4b0dfb32a32b8","cat":"rumah","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"saudara laki-laki\"?","ar":null,"explanation":"أَخٌ = saudara laki-laki. أُخْتٌ = saudara perempuan, اِبْنٌ = anak laki-laki, أَبٌ = ayah.","time":20,"options":["أَخٌ","أُخْتٌ","اِبْنٌ","أَبٌ"],"correct":1,"accepted":[]},{"key":"b72142060aec8394ec89b4c1f35b381c","cat":"rumah","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"عَمٌّ","explanation":"عَمٌّ = saudara laki-laki ayah. Saudara laki-laki ibu disebut خَالٌ.","time":25,"options":["Paman (saudara ayah)","Paman (saudara ibu)","Kakek","Sepupu"],"correct":1,"accepted":[]},{"key":"7dcaaea49f3e82dd4dccaec92f53b11f","cat":"makanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"خُبْزٌ","explanation":"خُبْزٌ = roti. Nasi = أَرُزٌّ, daging = لَحْمٌ, keju = جُبْنٌ.","time":20,"options":["Roti","Nasi","Daging","Keju"],"correct":1,"accepted":[]},{"key":"b87ea3b1a1f31e11ac7aad4aaec00221","cat":"makanan","type":"arabic_translation","level":"beginner","variety":"fusha","prompt":"Apa bahasa Arabnya \"susu\"?","ar":null,"explanation":"حَلِيبٌ = susu. عَصِيرٌ = jus, شَايٌ = teh, قَهْوَةٌ = kopi.","time":20,"options":["حَلِيبٌ","عَصِيرٌ","شَايٌ","قَهْوَةٌ"],"correct":1,"accepted":[]},{"key":"f413a4429380421cd94c560edcf4a468","cat":"makanan","type":"picture_vocabulary","level":"beginner","variety":"fusha","prompt":"Apa nama buah pada gambar dalam bahasa Arab?","ar":"🍎","explanation":"تُفَّاحٌ = apel. مَوْزٌ = pisang, بُرْتُقَالٌ = jeruk, عِنَبٌ = anggur.","time":20,"options":["تُفَّاحٌ","مَوْزٌ","بُرْتُقَالٌ","عِنَبٌ"],"correct":1,"accepted":[]},{"key":"57db8b5dcc33d8c2a65012a676b3aac0","cat":"makanan","type":"picture_vocabulary","level":"beginner","variety":"fusha","prompt":"Apa nama buah pada gambar dalam bahasa Arab?","ar":"🍌","explanation":"مَوْزٌ = pisang. تُفَّاحٌ = apel, رُمَّانٌ = delima, تَمْرٌ = kurma.","time":20,"options":["مَوْزٌ","تُفَّاحٌ","رُمَّانٌ","تَمْرٌ"],"correct":1,"accepted":[]},{"key":"c9b9be24cc57abaebcb0874eb6d477eb","cat":"aktivitas","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَنَامُ","explanation":"نَامَ – يَنَامُ = tidur.","time":20,"options":["Tidur","Makan","Mandi","Bangun"],"correct":1,"accepted":[]},{"key":"7ba07a202dbae2d2dcdd09957b64e8ab","cat":"aktivitas","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"يَسْتَيْقِظُ","explanation":"اِسْتَيْقَظَ – يَسْتَيْقِظُ = bangun (dari tidur).","time":25,"options":["Bangun tidur","Berwudu","Berangkat","Beristirahat"],"correct":1,"accepted":[]},{"key":"f47041cca5645ef701c86e2cb67ea554","cat":"aktivitas","type":"true_false","level":"beginner","variety":"fusha","prompt":"Benar atau salah? أَتَوَضَّأُ artinya \"saya berwudu\".","ar":"أَتَوَضَّأُ","explanation":"Benar. تَوَضَّأَ – يَتَوَضَّأُ = berwudu; huruf أَ di awal fi'il mudhari' menunjukkan \"saya\".","time":20,"options":["Benar","Salah"],"correct":1,"accepted":[]},{"key":"65fd7b81239b7ff4e6acb9a1cc9bb019","cat":"aktivitas","type":"sentence_builder","level":"intermediate","variety":"fusha","prompt":"Susun menjadi kalimat: \"Saya pergi ke sekolah setiap hari.\"","ar":null,"explanation":"أَذْهَبُ إِلَى الْمَدْرَسَةِ كُلَّ يَوْمٍ. Keterangan waktu كُلَّ يَوْمٍ juga boleh diletakkan di awal kalimat.","time":45,"options":["أَذْهَبُ","إِلَى","الْمَدْرَسَةِ","كُلَّ","يَوْمٍ"],"correct":null,"accepted":["أَذْهَبُ إِلَى الْمَدْرَسَةِ كُلَّ يَوْمٍ","كُلَّ يَوْمٍ أَذْهَبُ إِلَى الْمَدْرَسَةِ"]},{"key":"c9d7392db7265cd494a76788f1f2cf97","cat":"perjalanan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مَطَارٌ","explanation":"مَطَارٌ (dari طَارَ = terbang) = bandara. Stasiun = مَحَطَّةٌ, pelabuhan = مِينَاءٌ.","time":20,"options":["Bandara","Stasiun","Pelabuhan","Terminal"],"correct":1,"accepted":[]},{"key":"6162afe91fe135f4cabd94851c5ba3e9","cat":"perjalanan","type":"arabic_translation","level":"intermediate","variety":"fusha","prompt":"Apa bahasa Arabnya \"tiket\"?","ar":null,"explanation":"تَذْكِرَةٌ = tiket. حَقِيبَةٌ = tas/koper, جَوَازُ السَّفَرِ = paspor, طَائِرَةٌ = pesawat.","time":25,"options":["تَذْكِرَةٌ","حَقِيبَةٌ","جَوَازُ السَّفَرِ","طَائِرَةٌ"],"correct":1,"accepted":[]},{"key":"a70083e2479b5594dd9737fe69ea88b5","cat":"perjalanan","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Kamu ingin bertanya di mana stasiun kereta. Kalimat yang tepat adalah …","ar":null,"explanation":"أَيْنَ = di mana; مَحَطَّةُ الْقِطَارِ = stasiun kereta. Pilihan lain: \"Kapan kereta tiba?\", \"Berapa harga tiketnya?\", \"Apakah ini kursimu?\"","time":25,"options":["أَيْنَ مَحَطَّةُ الْقِطَارِ؟","مَتَى يَصِلُ الْقِطَارُ؟","كَمْ ثَمَنُ التَّذْكِرَةِ؟","هَلْ هَذَا مَقْعَدُكَ؟"],"correct":1,"accepted":[]},{"key":"e21f1cbf4a4a9390901ad9ae99b44aea","cat":"kampus","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مُحَاضَرَةٌ","explanation":"مُحَاضَرَةٌ = kuliah/ceramah ilmiah. Ujian = اِمْتِحَانٌ, perpustakaan = مَكْتَبَةٌ.","time":25,"options":["Kuliah (perkuliahan)","Ujian","Asrama","Perpustakaan"],"correct":1,"accepted":[]},{"key":"b72f7918609981ad0db6a6d855250fd0","cat":"kampus","type":"vocabulary_challenge","level":"intermediate","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"كُلِّيَّةٌ","explanation":"كُلِّيَّةٌ = fakultas. Jurusan = قِسْمٌ, universitas = جَامِعَةٌ, kelas = فَصْلٌ.","time":25,"options":["Fakultas","Jurusan","Universitas","Kelas"],"correct":1,"accepted":[]},{"key":"9ca5f1469503017462cc623a4c81aceb","cat":"kampus","type":"vocabulary_challenge","level":"advanced","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"مَرْجِعٌ","explanation":"مَرْجِعٌ (jamak: مَرَاجِعُ) = referensi/rujukan. Ringkasan = مُلَخَّصٌ, daftar isi = فِهْرِسٌ, catatan kaki = هَامِشٌ.","time":30,"options":["Referensi (rujukan)","Ringkasan","Daftar isi","Catatan kaki"],"correct":1,"accepted":[]},{"key":"6a641860704e77b5d2ee29030e720fd8","cat":"kampus","type":"arabic_translation","level":"advanced","variety":"fusha","prompt":"Apa bahasa Arabnya \"pengumuman\"?","ar":null,"explanation":"إِعْلَانٌ = pengumuman. Kata lain berakar mirip: إِعْلَامٌ = media/pemberitahuan, اِسْتِعْلَامٌ = bagian informasi, تَعْلِيمٌ = pengajaran.","time":30,"options":["إِعْلَانٌ","إِعْلَامٌ","اِسْتِعْلَامٌ","تَعْلِيمٌ"],"correct":1,"accepted":[]},{"key":"d6328650020969695f28d1af4f9e45a4","cat":"salam","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Temanmu berkata: السَّلَامُ عَلَيْكُمْ. Pilih respons yang paling tepat.","ar":"السَّلَامُ عَلَيْكُمْ","explanation":"Jawaban salam adalah وَعَلَيْكُمُ السَّلَامُ. مَعَ السَّلَامَةِ diucapkan saat berpisah.","time":20,"options":["وَعَلَيْكُمُ السَّلَامُ","صَبَاحَ النُّورِ","مَعَ السَّلَامَةِ","شُكْرًا"],"correct":1,"accepted":[]},{"key":"77f3287970d93a9bc162f0a693c2ee3b","cat":"salam","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Ustadz menyapa: صَبَاحَ الْخَيْرِ. Pilih respons yang paling tepat.","ar":"صَبَاحَ الْخَيْرِ","explanation":"صَبَاحَ الْخَيْرِ (selamat pagi) dijawab صَبَاحَ النُّورِ. مَسَاءَ النُّورِ untuk sore/malam.","time":20,"options":["صَبَاحَ النُّورِ","مَسَاءَ النُّورِ","عَفْوًا","إِلَى اللِّقَاءِ"],"correct":1,"accepted":[]},{"key":"caa3a509df7c57d6f59ed9b8a60d932a","cat":"salam","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Seseorang bertanya: مَا اسْمُكَ؟ Pilih respons yang paling tepat.","ar":"مَا اسْمُكَ؟","explanation":"مَا اسْمُكَ؟ = Siapa namamu? Jawabannya اِسْمِي ... (namaku ...).","time":20,"options":["اِسْمِي أَحْمَدُ.","أَنَا مِنْ إِنْدُونِيسِيَا.","عُمْرِي عِشْرُونَ سَنَةً.","أَنَا بِخَيْرٍ."],"correct":1,"accepted":[]},{"key":"b240efae126b427b6fd7f1267c342b22","cat":"salam","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Seseorang bertanya: مِنْ أَيْنَ أَنْتَ؟ Pilih respons yang paling tepat.","ar":"مِنْ أَيْنَ أَنْتَ؟","explanation":"مِنْ أَيْنَ أَنْتَ؟ = Dari mana asalmu? Jawabannya أَنَا مِنْ ... . \"أَسْكُنُ فِي الْقَاهِرَةِ\" menjawab tempat tinggal, bukan asal.","time":25,"options":["أَنَا مِنْ إِنْدُونِيسِيَا.","اِسْمِي أَحْمَدُ.","أَسْكُنُ فِي الْقَاهِرَةِ مُنْذُ سَنَةٍ.","أَنَا طَالِبٌ."],"correct":1,"accepted":[]},{"key":"18c7bff49eac7277aa224ed130c62c2d","cat":"salam","type":"complete_expression","level":"beginner","variety":"fusha","prompt":"Lengkapi ungkapan \"Apa kabarmu?\"","ar":"كَيْفَ ـــــ ؟","explanation":"كَيْفَ حَالُكَ؟ = Bagaimana keadaanmu/apa kabarmu? Untuk perempuan: كَيْفَ حَالُكِ؟","time":20,"options":["حَالُكَ","اسْمُكَ","بَيْتُكَ","عُمْرُكَ"],"correct":1,"accepted":[]},{"key":"e3c02297cd8767539bf9aa1143b66d79","cat":"pasar","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti kata berikut?","ar":"سُوقٌ","explanation":"سُوقٌ = pasar (jamak: أَسْوَاقٌ). Toko = دُكَّانٌ atau مَحَلٌّ, jalan = شَارِعٌ.","time":20,"options":["Pasar","Toko","Masjid","Jalan"],"correct":1,"accepted":[]},{"key":"0c95471b4a01e6b2d06e0fc82b2bb176","cat":"pasar","type":"daily_conversation","level":"beginner","variety":"fusha","prompt":"Di pasar kamu mendengar: بِكَمْ هَذَا؟ Artinya …","ar":"بِكَمْ هَذَا؟","explanation":"بِكَمْ = dengan (harga) berapa. Di mana = أَيْنَ, apa = مَا, milik siapa = لِمَنْ.","time":20,"options":["Berapa harga ini?","Di mana ini?","Apa ini?","Milik siapa ini?"],"correct":1,"accepted":[]},{"key":"3428adcb8739b323957390c4741f41eb","cat":"pasar","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Di restoran kamu ingin meminta daftar menu. Kalimat yang tepat adalah …","ar":null,"explanation":"قَائِمَةُ الطَّعَامِ = daftar menu. أَنَا شَبْعَانُ = saya kenyang, الْحِسَابُ = tagihan, لَذِيذٌ = lezat.","time":25,"options":["مِنْ فَضْلِكَ، أَعْطِنِي قَائِمَةَ الطَّعَامِ.","أَنَا شَبْعَانُ.","الْحِسَابُ مِنْ فَضْلِكَ.","الطَّعَامُ لَذِيذٌ."],"correct":1,"accepted":[]},{"key":"62e7f2fcd32b6b02b923ff3440e7783c","cat":"ungkapan","type":"complete_expression","level":"beginner","variety":"fusha","prompt":"Ketika bersin, kita disunnahkan mengucapkan …","ar":"ـــــ لِلّٰهِ","explanation":"Sunnah ketika bersin adalah mengucapkan الْحَمْدُ لِلّٰهِ.","time":20,"options":["الْحَمْدُ","الشُّكْرُ","السَّلَامُ","الْعَفْوُ"],"correct":1,"accepted":[]},{"key":"1bada28c1112d68c5425c35d292b7e09","cat":"ungkapan","type":"complete_expression","level":"intermediate","variety":"fusha","prompt":"Temanmu bersin lalu mengucap الْحَمْدُ لِلّٰهِ. Kamu menjawab …","ar":"ـــــ اللّٰهُ","explanation":"Pendengar menjawab يَرْحَمُكَ اللّٰهُ. Lalu yang bersin membalas يَهْدِيكُمُ اللّٰهُ وَيُصْلِحُ بَالَكُمْ.","time":25,"options":["يَرْحَمُكَ","يَهْدِيكُمُ","يَحْفَظُكَ","يُبَارِكُ"],"correct":1,"accepted":[]},{"key":"962aa7cf0389d9e736a0490525dad380","cat":"ungkapan","type":"vocabulary_challenge","level":"beginner","variety":"fusha","prompt":"Apa arti ungkapan berikut ketika menjawab شُكْرًا?","ar":"عَفْوًا","explanation":"عَفْوًا sebagai jawaban شُكْرًا berarti \"sama-sama\". Dalam konteks lain ia juga berarti \"maaf/permisi\".","time":20,"options":["Sama-sama","Terima kasih","Selamat tinggal","Silakan masuk"],"correct":1,"accepted":[]},{"key":"c7ee800c530103b491dd1b77c6fcc3be","cat":"ungkapan","type":"true_false","level":"intermediate","variety":"fusha","prompt":"Benar atau salah? إِنْ شَاءَ اللّٰهُ diucapkan untuk sesuatu yang sudah terjadi.","ar":"إِنْ شَاءَ اللّٰهُ","explanation":"Salah. إِنْ شَاءَ اللّٰهُ diucapkan untuk rencana di masa depan. Untuk kekaguman atas sesuatu yang ada diucapkan مَا شَاءَ اللّٰهُ.","time":25,"options":["Benar","Salah"],"correct":2,"accepted":[]},{"key":"8d86629ff8deb777d53a707d83471cfd","cat":"fusha","type":"daily_conversation","level":"intermediate","variety":"fusha","prompt":"Pilih respons yang paling tepat.","ar":"هَلْ تَتَكَلَّمُ اللُّغَةَ الْعَرَبِيَّةَ؟","explanation":"Pertanyaan: \"Apakah kamu berbicara bahasa Arab?\" Jawaban yang sesuai: \"Ya, saya berbicara sedikit.\" (أَتَكَلَّمُهَا = saya berbicara dengannya).","time":25,"options":["نَعَمْ، أَتَكَلَّمُهَا قَلِيلًا.","نَعَمْ، أَنَا طَالِبٌ.","لَا، أَنَا جَائِعٌ.","نَعَمْ، الْكِتَابُ جَدِيدٌ."],"correct":1,"accepted":[]},{"key":"80db5d09499c279b3f6c49da1b55f385","cat":"fusha","type":"daily_conversation","level":"advanced","variety":"fusha","prompt":"Pilih respons yang paling tepat.","ar":"مَاذَا تَدْرُسُ فِي الْجَامِعَةِ؟","explanation":"Pertanyaan: \"Apa yang kamu pelajari di universitas?\" Jawaban yang tepat menyebut bidang studi. دَرَسْتُ أَمْسِ menjawab waktu belajar (fi'il madhi), bukan bidang studi.","time":30,"options":["أَدْرُسُ فِي كُلِّيَّةِ أُصُولِ الدِّينِ.","أَسْكُنُ قَرِيبًا مِنَ الْجَامِعَةِ.","دَرَسْتُ أَمْسِ مَعَ صَدِيقِي.","الْجَامِعَةُ كَبِيرَةٌ جِدًّا."],"correct":1,"accepted":[]},{"key":"c52ff9405efa85e18ae40b500bbf231f","cat":"fusha","type":"sentence_builder","level":"advanced","variety":"fusha","prompt":"Susun menjadi jumlah fi'liyyah (diawali fi'il): \"Mahasiswa itu telah membaca buku di perpustakaan.\"","ar":null,"explanation":"Urutan dasar jumlah fi'liyyah: fi'il (قَرَأَ) – fa'il marfu' (الطَّالِبُ) – maf'ul bih manshub (الْكِتَابَ) – keterangan tempat (فِي الْمَكْتَبَةِ).","time":45,"options":["قَرَأَ","الطَّالِبُ","الْكِتَابَ","فِي","الْمَكْتَبَةِ"],"correct":null,"accepted":["قَرَأَ الطَّالِبُ الْكِتَابَ فِي الْمَكْتَبَةِ","قَرَأَ الطَّالِبُ فِي الْمَكْتَبَةِ الْكِتَابَ"]},{"key":"1f3781372b8ee6a5e2a49e00c5668b38","cat":"fusha","type":"context_challenge","level":"intermediate","variety":"fusha","prompt":"Kamu terlambat masuk kelas. Kalimat yang sopan kepada ustadz adalah …","ar":null,"explanation":"تَأَخَّرْتُ = saya terlambat; diawali عَفْوًا (maaf). Pilihan lain: \"Di mana ustadz?\", \"Saya terburu-buru.\", \"Sampai jumpa, ustadz.\"","time":25,"options":["عَفْوًا يَا أُسْتَاذُ، تَأَخَّرْتُ.","أَيْنَ الْأُسْتَاذُ؟","أَنَا مُسْتَعْجِلٌ.","إِلَى اللِّقَاءِ يَا أُسْتَاذُ."],"correct":1,"accepted":[]},{"key":"64473d48ed931632518fb6fee8d48086","cat":"amiyah","type":"amiyah_challenge","level":"beginner","variety":"amiyah_mesir","prompt":"Apa arti ungkapan Amiyah Mesir ini?","ar":"إِزَّيَّك؟","explanation":"إِزَّيَّك = apa kabar? (Fusha: كَيْفَ حَالُكَ؟). Untuk perempuan diucapkan إِزَّيِّك.","time":20,"options":["Apa kabar?","Di mana kamu?","Siapa namamu?","Mau ke mana?"],"correct":1,"accepted":[]},{"key":"b7867cbb067f5f8eae83b57795d759b8","cat":"amiyah","type":"amiyah_challenge","level":"beginner","variety":"amiyah_mesir","prompt":"Apa arti kata Amiyah Mesir ini?","ar":"عَايِز","explanation":"عَايِز (laki-laki) / عَايْزَة (perempuan) = mau/ingin. Padanan Fusha: أُرِيدُ.","time":20,"options":["Mau / ingin","Tahu","Bisa","Punya"],"correct":1,"accepted":[]},{"key":"652bdfbdf3edf2300a9c375cb48809a1","cat":"amiyah","type":"amiyah_challenge","level":"intermediate","variety":"amiyah_mesir","prompt":"Apa padanan Fusha dari kata Amiyah ini?","ar":"دِلْوَقْتِي","explanation":"دِلْوَقْتِي = sekarang, padanan Fusha الْآنَ. غَدًا = besok, أَمْسِ = kemarin, بَعْدَ قَلِيلٍ = sebentar lagi.","time":25,"options":["الْآنَ","غَدًا","أَمْسِ","بَعْدَ قَلِيلٍ"],"correct":1,"accepted":[]},{"key":"389ea93aba12de05508a53f8c22a96d4","cat":"amiyah","type":"amiyah_challenge","level":"intermediate","variety":"amiyah_mesir","prompt":"Apa arti ungkapan Amiyah Mesir ini?","ar":"مِشْ عَارِف","explanation":"مِشْ = tidak (negasi Amiyah), عَارِف = tahu. Padanan Fusha: لَا أَعْرِفُ.","time":25,"options":["Saya tidak tahu","Saya tidak mau","Saya belum makan","Saya tidak bisa"],"correct":1,"accepted":[]},{"key":"fe11478d0cafb7d587d69bbad0f4c731","cat":"amiyah","type":"amiyah_challenge","level":"advanced","variety":"amiyah_mesir","prompt":"Sopir taksi di Kairo bertanya kepadamu. Maksudnya …","ar":"رَايِح فِين؟","explanation":"رَايِح = pergi/menuju (Fusha: ذَاهِبٌ), فِين = di mana/ke mana (Fusha: أَيْنَ). Jadi: إِلَى أَيْنَ أَنْتَ ذَاهِبٌ؟","time":30,"options":["Mau ke mana?","Dari mana?","Kapan berangkat?","Berapa orang?"],"correct":1,"accepted":[]},{"key":"5d6d2b09d16ccf0f088a032f5135f849","cat":"amiyah","type":"amiyah_challenge","level":"advanced","variety":"amiyah_mesir","prompt":"Ungkapan Amiyah Mesir ini biasanya dipakai untuk …","ar":"مَعْلِش","explanation":"مَعْلِش (dari مَا عَلَيْهِ شَيْءٌ) = tidak apa-apa / maaf ya. Sangat sering dipakai di Mesir.","time":30,"options":["Menenangkan/memaafkan: \"tidak apa-apa\"","Menolak dengan tegas","Memuji makanan","Memanggil pelayan"],"correct":1,"accepted":[]},{"key":"99b138147a909bf6e2342a1e87b55267","cat":"mubtada-khabar","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"[[الْكِتَابُ]] جَدِيدٌ","explanation":"الْكِتَابُ adalah mubtada': isim marfu' di awal jumlah ismiyyah yang menjadi pokok pembicaraan. Tanda rafa'-nya dhammah. جَدِيدٌ adalah khabarnya.","time":20,"options":["Mubtada' marfu' dengan dhammah","Khabar marfu' dengan dhammah","Fa'il marfu' dengan dhammah","Maf'ul bih manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"544ebaf6af8db2e60b2f92ba1605b8b5","cat":"mubtada-khabar","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"الْمَسْجِدُ [[كَبِيرٌ]]","explanation":"كَبِيرٌ adalah khabar: bagian yang menyempurnakan makna mubtada' الْمَسْجِدُ. Khabar selalu marfu', tandanya dhammah (tanwin).","time":20,"options":["Khabar marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Na'at marfu' dengan dhammah","Hal manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"1321ecb9d91e4f961d28c181bec30bdd","cat":"mubtada-khabar","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"فِي الْفَصْلِ [[طُلَّابٌ]]","explanation":"طُلَّابٌ adalah mubtada' muakhkhar (diakhirkan). Karena mubtada'-nya nakirah dan khabarnya syibhu jumlah (فِي الْفَصْلِ), khabar wajib didahulukan (khabar muqaddam).","time":25,"options":["Mubtada' muakhkhar marfu' dengan dhammah","Khabar marfu' dengan dhammah","Fa'il marfu' dengan dhammah","Na'at marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"1bcd03585008a42a9bbab1ef4839f4fa","cat":"mubtada-khabar","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Khabar pada kalimat berikut berbentuk …","ar":"الطَّالِبُ يَقْرَأُ الْقُرْآنَ","explanation":"Khabar dari الطَّالِبُ adalah يَقْرَأُ الْقُرْآنَ, yaitu jumlah fi'liyyah (fi'il + fa'il dhamir mustatir + maf'ul bih). Jumlah ini berkedudukan rafa' sebagai khabar (fi mahalli raf'in).","time":30,"options":["Jumlah fi'liyyah","Mufrad","Syibhu jumlah","Jumlah ismiyyah"],"correct":1,"accepted":[]},{"key":"fb2c9d9413630e8991c786c3619e7271","cat":"fail","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ [[الْمُدَرِّسُ]]","explanation":"الْمُدَرِّسُ adalah fa'il: isim marfu' setelah fi'il ma'lum yang menunjukkan pelaku. Tanda rafa'-nya dhammah.","time":20,"options":["Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Maf'ul bih manshub dengan fathah","Khabar marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"8c74e0ea2272893c99aad89613d768ce","cat":"fail","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"نَجَحَ [[الْمُهَنْدِسُونَ]]","explanation":"الْمُهَنْدِسُونَ adalah fa'il. Jamak mudzakkar salim di-rafa'-kan dengan wawu sebagai pengganti dhammah (tanda i'rab far'i).","time":25,"options":["Fa'il marfu' dengan wawu karena jamak mudzakkar salim","Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan wawu","Fa'il manshub dengan ya'"],"correct":1,"accepted":[]},{"key":"621827d6085e8370f588d5eb7b711edb","cat":"fail","type":"grammar_detective","level":"intermediate","variety":"fusha","prompt":"Kalimat manakah yang SALAH?","ar":null,"explanation":"Jika fa'il-nya muannats haqiqi (perempuan sungguhan) dan langsung setelah fi'il, fi'il wajib diberi ta' ta'nits: قَامَتْ فَاطِمَةُ. Maka قَامَ فَاطِمَةُ salah.","time":25,"options":["قَامَ فَاطِمَةُ","قَامَتْ فَاطِمَةُ","جَلَسَ الطُّلَّابُ","نَجَحَ مُحَمَّدٌ"],"correct":1,"accepted":[]},{"key":"428f94918b3badbf82006780d88d9ba9","cat":"maful-bih","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"كَتَبَ الطَّالِبُ [[الدَّرْسَ]]","explanation":"الدَّرْسَ adalah maf'ul bih: isim manshub yang dikenai pekerjaan. Tanda nashab-nya fathah.","time":20,"options":["Maf'ul bih manshub dengan fathah","Fa'il marfu' dengan dhammah","Mudhaf ilaih majrur dengan kasrah","Hal manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"f7922d6f8871c3843c6446ed4f5d56a9","cat":"maful-bih","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"رَأَيْتُ [[الْمُعَلِّمِينَ]]","explanation":"الْمُعَلِّمِينَ adalah maf'ul bih. Jamak mudzakkar salim di-nashab-kan dengan ya' sebagai pengganti fathah.","time":25,"options":["Maf'ul bih manshub dengan ya' karena jamak mudzakkar salim","Maf'ul bih manshub dengan fathah","Fa'il marfu' dengan wawu","Isim majrur dengan ya'"],"correct":1,"accepted":[]},{"key":"b2a305e5869407dc7ec5f476617cf28e","cat":"maful-bih","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"شَاهَدْتُ [[الطَّالِبَاتِ]]","explanation":"الطَّالِبَاتِ adalah maf'ul bih. Jamak muannats salim di-nashab-kan dengan kasrah sebagai pengganti fathah. Jadi kasrah di sini bukan tanda jarr.","time":25,"options":["Maf'ul bih manshub dengan kasrah karena jamak muannats salim","Maf'ul bih manshub dengan fathah","Isim majrur dengan kasrah","Mudhaf ilaih majrur dengan kasrah"],"correct":1,"accepted":[]},{"key":"75807726fefc7a1c70bbde06b6a49c53","cat":"maful-bih","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"قَرَأَ [[الْقُرْآنَ]] أَحْمَدُ","explanation":"الْقُرْآنَ tetap maf'ul bih meskipun disebut sebelum fa'il أَحْمَدُ (maf'ul bih muqaddam). Tandanya fathah. أَحْمَدُ adalah fa'il marfu' (mamnu' min ash-sharf, tanpa tanwin).","time":30,"options":["Maf'ul bih manshub dengan fathah (didahulukan dari fa'il)","Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Hal manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"b0a11607e762151721b7a7b84aabe0ab","cat":"naat","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"هَذَا بَيْتٌ [[جَمِيلٌ]]","explanation":"جَمِيلٌ adalah na'at (sifat) bagi بَيْتٌ. Na'at mengikuti man'ut-nya dalam i'rab: بَيْتٌ marfu' (khabar), maka جَمِيلٌ juga marfu'.","time":20,"options":["Na'at marfu' dengan dhammah, mengikuti man'ut-nya","Khabar marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Hal manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"6b79054ceb0a5a02fabc24fd26d32e03","cat":"naat","type":"nahwu_battle","level":"intermediate","variety":"fusha","prompt":"Pilih na'at yang tepat untuk melengkapi kalimat.","ar":"رَأَيْتُ بِنْتًا ـــــ","explanation":"Na'at mengikuti man'ut dalam i'rab (manshub), jenis (muannats), dan nakirah/ma'rifah. بِنْتًا manshub, muannats, nakirah, maka na'at-nya صَغِيرَةً.","time":25,"options":["صَغِيرَةً","صَغِيرٌ","صَغِيرَةٌ","الصَّغِيرَةَ"],"correct":1,"accepted":[]},{"key":"de3ad6c5697e54cd24bd13c0be74c91c","cat":"naat","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"مَرَرْتُ بِالطُّلَّابِ [[الْمُجْتَهِدِينَ]]","explanation":"الْمُجْتَهِدِينَ adalah na'at bagi الطُّلَّابِ yang majrur oleh بِـ. Na'at ikut majrur; karena berbentuk jamak mudzakkar salim, tanda jarr-nya ya'. Bukan hal, karena hal harus nakirah.","time":30,"options":["Na'at majrur dengan ya' karena jamak mudzakkar salim","Na'at majrur dengan kasrah","Maf'ul bih manshub dengan ya'","Hal manshub dengan ya'"],"correct":1,"accepted":[]},{"key":"0a1f1c2b213ea8ed8bba6ad575da53b2","cat":"idhafah","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"هَذَا كِتَابُ [[الطَّالِبِ]]","explanation":"الطَّالِبِ adalah mudhaf ilaih. Mudhaf ilaih selalu majrur; tandanya kasrah. كِتَابُ adalah mudhaf (tanpa ال dan tanpa tanwin).","time":20,"options":["Mudhaf ilaih majrur dengan kasrah","Na'at majrur dengan kasrah","Isim majrur oleh huruf jar","Maf'ul bih manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"a26f984e03ef9badd78c8441bf960f4b","cat":"idhafah","type":"grammar_detective","level":"intermediate","variety":"fusha","prompt":"Kalimat manakah yang SALAH?","ar":null,"explanation":"Dalam idhafah, mudhaf tidak boleh diberi ال dan tidak bertanwin. Yang benar: هَذَا كِتَابُ الطَّالِبِ.","time":25,"options":["هَذَا الْكِتَابُ الطَّالِبِ","هَذَا كِتَابُ الطَّالِبِ","هَذَا كِتَابٌ جَدِيدٌ","هَذَا بَابُ الْفَصْلِ"],"correct":1,"accepted":[]},{"key":"7117b3c655b965b81176301467bc93a5","cat":"idhafah","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ [[مُعَلِّمُو]] الْمَدْرَسَةِ","explanation":"مُعَلِّمُو asalnya مُعَلِّمُونَ (jamak mudzakkar salim), fa'il marfu' dengan wawu. Nun-nya dibuang karena menjadi mudhaf bagi الْمَدْرَسَةِ.","time":30,"options":["Fa'il marfu' dengan wawu; nun jamak dibuang karena idhafah","Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan wawu","Mudhaf ilaih majrur"],"correct":1,"accepted":[]},{"key":"c3730b3620f6f3188d35b7e37f0175da","cat":"hal","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ الطَّالِبُ [[مُبْتَسِمًا]]","explanation":"مُبْتَسِمًا adalah hal: isim nakirah manshub yang menjelaskan keadaan shahibul hal (الطَّالِبُ) saat terjadinya pekerjaan.","time":25,"options":["Hal manshub dengan fathah","Maf'ul bih manshub dengan fathah","Na'at manshub dengan fathah","Tamyiz manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"68739e7ee819dfba1af32b82c6c45aad","cat":"hal","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Pilih hal yang tepat untuk melengkapi kalimat.","ar":"رَجَعَ الْجُنُودُ ـــــ","explanation":"Hal harus nakirah dan manshub, serta sesuai dengan shahibul hal. الْجُنُودُ jamak, maka hal-nya jamak mudzakkar salim manshub dengan ya': مُنْتَصِرِينَ.","time":30,"options":["مُنْتَصِرِينَ","مُنْتَصِرُونَ","الْمُنْتَصِرِينَ","مُنْتَصِرًا"],"correct":1,"accepted":[]},{"key":"3adfd49d62ef201e747882acbca6564b","cat":"tamyiz","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"اِشْتَرَيْتُ عِشْرِينَ [[كِتَابًا]]","explanation":"كِتَابًا adalah tamyiz bilangan (tamyiz 'adad): menjelaskan apa yang dihitung. Tamyiz bilangan 11–99 berupa isim mufrad manshub.","time":25,"options":["Tamyiz manshub dengan fathah","Maf'ul bih manshub dengan fathah","Hal manshub dengan fathah","Mudhaf ilaih majrur"],"correct":1,"accepted":[]},{"key":"455ea25213731e28de0aee36ae658bd1","cat":"tamyiz","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Pilih tamyiz yang tepat untuk melengkapi kalimat.","ar":"عِنْدِي ثَلَاثَةُ ـــــ","explanation":"Tamyiz bilangan 3–10 berupa isim jamak yang majrur sebagai mudhaf ilaih: ثَلَاثَةُ كُتُبٍ.","time":30,"options":["كُتُبٍ","كُتُبًا","كِتَابٍ","كِتَابًا"],"correct":1,"accepted":[]},{"key":"ce9a158472200f0a9a7490ff90d4bba0","cat":"nawasikh","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"كَانَ الْجَوُّ [[بَارِدًا]]","explanation":"كَانَ me-rafa'-kan isimnya (الْجَوُّ) dan me-nashab-kan khabarnya. بَارِدًا adalah khabar kana, manshub dengan fathah.","time":25,"options":["Khabar kana manshub dengan fathah","Isim kana marfu' dengan dhammah","Hal manshub dengan fathah","Maf'ul bih manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"d0fcaa6cb672e1c03223ed193853abaa","cat":"nawasikh","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"إِنَّ [[اللّٰهَ]] غَفُورٌ","explanation":"إِنَّ me-nashab-kan isimnya dan me-rafa'-kan khabarnya (kebalikan dari كَانَ). اللّٰهَ adalah isim inna, manshub dengan fathah; غَفُورٌ khabar inna.","time":25,"options":["Isim inna manshub dengan fathah","Khabar inna marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Maf'ul bih manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"7d5cbd4e604c859c27f42d75b357247c","cat":"nawasikh","type":"nahwu_battle","level":"advanced","variety":"fusha","prompt":"Pilih bentuk yang benar untuk melengkapi kalimat.","ar":"إِنَّ الطُّلَّابَ ـــــ","explanation":"Kata yang kosong adalah khabar inna, maka marfu'. Karena jamak mudzakkar salim, tanda rafa'-nya wawu: مُجْتَهِدُونَ.","time":30,"options":["مُجْتَهِدُونَ","مُجْتَهِدِينَ","مُجْتَهِدًا","مُجْتَهِدُوا"],"correct":1,"accepted":[]},{"key":"b3f5ce3b7e40ebd4c644db6b83bf1115","cat":"majrurat","type":"irab_challenge","level":"beginner","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"ذَهَبْتُ إِلَى [[الْمَسْجِدِ]]","explanation":"الْمَسْجِدِ didahului huruf jar إِلَى, maka majrur dengan kasrah.","time":20,"options":["Isim majrur oleh huruf jar dengan kasrah","Mudhaf ilaih majrur dengan kasrah","Maf'ul bih manshub dengan fathah","Na'at majrur dengan kasrah"],"correct":1,"accepted":[]},{"key":"8f809ba971e779db69d11a77a91473cc","cat":"majrurat","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"صَلَّيْتُ فِي [[مَسَاجِدَ]] كَثِيرَةٍ","explanation":"مَسَاجِدَ majrur oleh فِي, tetapi tandanya fathah karena isim ghairu munsharif (shighat muntahal jumu': wazan مَفَاعِلُ) yang tidak ber-ال dan tidak di-idhafah-kan.","time":30,"options":["Isim majrur dengan fathah karena mamnu' min ash-sharf","Isim majrur dengan kasrah","Maf'ul bih manshub dengan fathah","Hal manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"f199aeb3de77239976fdf0bc3230c146","cat":"tawabi","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ مُحَمَّدٌ وَ[[عَلِيٌّ]]","explanation":"عَلِيٌّ di-'athaf-kan (disambung) kepada مُحَمَّدٌ dengan huruf وَ. Ma'thuf mengikuti ma'thuf 'alaih dalam i'rab, maka marfu'.","time":25,"options":["Ma'thuf marfu' dengan dhammah, mengikuti مُحَمَّدٌ","Badal marfu' dengan dhammah","Mubtada' marfu' dengan dhammah","Khabar marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"fa027be6a70c8c47752b0586283ca692","cat":"tawabi","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ الطُّلَّابُ [[كُلُّهُمْ]]","explanation":"كُلُّ yang bersambung dengan dhamir kembali ke kata sebelumnya adalah taukid ma'nawi. Ia mengikuti الطُّلَّابُ (fa'il) sehingga marfu'.","time":30,"options":["Taukid ma'nawi marfu' dengan dhammah","Na'at marfu' dengan dhammah","Fa'il marfu' dengan dhammah","Mubtada' marfu' dengan dhammah"],"correct":1,"accepted":[]},{"key":"ccc7c35fd4913309b85e48448a9f8d89","cat":"anwa-jumal","type":"sentence_analysis","level":"beginner","variety":"fusha","prompt":"Termasuk jenis jumlah apakah kalimat ini?","ar":"الْعِلْمُ نُورٌ","explanation":"Diawali isim (الْعِلْمُ) sebagai mubtada' dan diikuti khabar, maka jumlah ismiyyah.","time":20,"options":["Jumlah ismiyyah","Jumlah fi'liyyah","Syibhu jumlah"],"correct":1,"accepted":[]},{"key":"02708f8a8af58614143e86dcae072722","cat":"anwa-jumal","type":"sentence_analysis","level":"beginner","variety":"fusha","prompt":"Termasuk jenis jumlah apakah kalimat ini?","ar":"يَدْرُسُ الطَّالِبُ","explanation":"Diawali fi'il (يَدْرُسُ) lalu fa'il (الطَّالِبُ), maka jumlah fi'liyyah.","time":20,"options":["Jumlah fi'liyyah","Jumlah ismiyyah","Syibhu jumlah"],"correct":1,"accepted":[]},{"key":"b8766b2b83210e8e7c86b8f461982b0e","cat":"anwa-jumal","type":"identify_word","level":"beginner","variety":"fusha","prompt":"Kata yang ditandai termasuk jenis kalimah apa?","ar":"[[فِي]] الْبَيْتِ","explanation":"فِي adalah huruf (huruf jar): tidak bermakna sempurna kecuali bersama kata lain, dan tidak menerima tanda isim maupun fi'il.","time":20,"options":["Huruf","Isim","Fi'il"],"correct":1,"accepted":[]},{"key":"511c30305c98e54c21aaa6ac3637e257","cat":"anwa-jumal","type":"identify_word","level":"beginner","variety":"fusha","prompt":"Kata ini termasuk jenis kalimah apa?","ar":"الْمَدْرَسَةُ","explanation":"الْمَدْرَسَةُ adalah isim. Tandanya: menerima ال dan bisa bertanwin.","time":20,"options":["Isim","Fi'il","Huruf"],"correct":1,"accepted":[]},{"key":"3a8fab8977ce453d698704e36aefcde0","cat":"anwa-jumal","type":"identify_word","level":"advanced","variety":"fusha","prompt":"Kata ini termasuk jenis kalimah apa?","ar":"لَيْسَ","explanation":"لَيْسَ adalah fi'il madhi jamid (tidak bisa di-tashrif penuh). Buktinya ia menerima ta' fa'il: لَسْتُ، لَسْنَا.","time":30,"options":["Fi'il","Huruf","Isim"],"correct":1,"accepted":[]},{"key":"44291d626e88867db39635eab9b55776","cat":"anwa-jumal","type":"sentence_builder","level":"intermediate","variety":"fusha","prompt":"Susun menjadi jumlah ismiyyah yang diawali mubtada': \"Guru itu berada di kelas.\"","ar":null,"explanation":"Mubtada' (الْمُدَرِّسُ) di awal, lalu khabar berupa syibhu jumlah (jar-majrur) فِي الْفَصْلِ.","time":45,"options":["الْمُدَرِّسُ","فِي","الْفَصْلِ"],"correct":null,"accepted":["الْمُدَرِّسُ فِي الْفَصْلِ"]},{"key":"c3ecbd699ca956188c5e9155ae1dd5d4","cat":"madhi","type":"fiil_challenge","level":"beginner","variety":"fusha","prompt":"Kata ini termasuk fi'il apa?","ar":"كَتَبَ","explanation":"كَتَبَ adalah fi'il madhi (lampau): tiga huruf dengan harakat fathah di akhir, tanpa huruf mudhara'ah.","time":20,"options":["Fi'il madhi","Fi'il mudhari'","Fi'il amr"],"correct":1,"accepted":[]},{"key":"5cd683b39ec3af964b72682540132b0e","cat":"madhi","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Ubah كَتَبَ untuk dhamir هُمْ (mereka laki-laki).","ar":null,"explanation":"Untuk هُمْ ditambahkan wawu jama'ah (dan alif fariqah): كَتَبُوا. كَتَبْنَ untuk هُنَّ, كَتَبْتُمْ untuk أَنْتُمْ, كَتَبَا untuk هُمَا.","time":25,"options":["كَتَبُوا","كَتَبْنَ","كَتَبْتُمْ","كَتَبَا"],"correct":1,"accepted":[]},{"key":"d89d89f5f9a6f4d1c3890b3a9885148b","cat":"madhi","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Ubah كَتَبَ untuk dhamir أَنْتِ (kamu perempuan).","ar":null,"explanation":"أَنْتِ → ta' fa'il berharakat kasrah: كَتَبْتِ. كَتَبْتَ untuk أَنْتَ, كَتَبَتْ untuk هِيَ, كَتَبْتُ untuk أَنَا.","time":25,"options":["كَتَبْتِ","كَتَبْتَ","كَتَبَتْ","كَتَبْتُ"],"correct":1,"accepted":[]},{"key":"8c6805487beb1707a52477174d43c29f","cat":"madhi","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Ubah قَالَ untuk dhamir أَنَا.","ar":null,"explanation":"قَالَ asalnya قَوَلَ (ajwaf wawi). Saat bertemu ta' fa'il yang membuat lam fi'il sukun, alif dibuang (iltiqa' sakinain) dan fa' fi'il didhammah sebagai tanda asal wawu: قُلْتُ.","time":30,"options":["قُلْتُ","قَالْتُ","قِلْتُ","قَوَلْتُ"],"correct":1,"accepted":[]},{"key":"bb323c9af8e049eaf8115d7e196431e9","cat":"mudhari","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa fi'il mudhari' dari كَتَبَ untuk dhamir هُوَ?","ar":null,"explanation":"كَتَبَ – يَكْتُبُ (bab نَصَرَ – يَنْصُرُ: 'ain mudhari' berharakat dhammah). Untuk هُوَ huruf mudhara'ah-nya يَـ.","time":20,"options":["يَكْتُبُ","يَكْتِبُ","يَكْتَبُ","تَكْتُبُ"],"correct":1,"accepted":[]},{"key":"4e33127818c09b12cad74761458a1793","cat":"mudhari","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa fi'il mudhari' dari ذَهَبَ untuk dhamir هُنَّ?","ar":null,"explanation":"هُنَّ → يَذْهَبْنَ (nun niswah). يَذْهَبُونَ untuk هُمْ, تَذْهَبْنَ untuk أَنْتُنَّ, يَذْهَبَانِ untuk هُمَا.","time":25,"options":["يَذْهَبْنَ","يَذْهَبُونَ","تَذْهَبْنَ","يَذْهَبَانِ"],"correct":1,"accepted":[]},{"key":"91280b27db508414c5c1df895dc6b7c7","cat":"mudhari","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa fi'il mudhari' dari أَكْرَمَ untuk dhamir هُوَ?","ar":null,"explanation":"أَكْرَمَ berwazan أَفْعَلَ, mudhari'-nya يُفْعِلُ: يُكْرِمُ. Huruf mudhara'ah fi'il ruba'i didhammah dan hamzah أَفْعَلَ dibuang.","time":30,"options":["يُكْرِمُ","يَكْرُمُ","يُكَرِّمُ","يَتَكَرَّمُ"],"correct":1,"accepted":[]},{"key":"8f497476bbd0c959e85ae370a0dd7049","cat":"amr","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa fi'il amr dari يَكْتُبُ (untuk أَنْتَ)?","ar":null,"explanation":"Buang huruf mudhara'ah dan sukunkan akhirnya: كْتُبْ. Karena huruf pertama sukun, ditambah hamzah washl; hamzahnya didhammah karena 'ain fi'il-nya dhammah: اُكْتُبْ.","time":20,"options":["اُكْتُبْ","اِكْتِبْ","كْتُبْ","تَكْتُبْ"],"correct":1,"accepted":[]},{"key":"8951a35121d0970907d39f5927b6e1c4","cat":"amr","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa fi'il amr dari يَجْلِسُ untuk dhamir أَنْتُمْ?","ar":null,"explanation":"Amr untuk أَنْتُمْ: اِجْلِسُوا. Hamzah washl dikasrah karena 'ain fi'il-nya kasrah; nun dibuang seperti pada af'al khamsah yang majzum.","time":25,"options":["اِجْلِسُوا","اُجْلُسُوا","اِجْلِسُونَ","تَجْلِسُوا"],"correct":1,"accepted":[]},{"key":"928a4686f5055e40709473aa485f1c81","cat":"amr","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa fi'il amr dari يَقُومُ (untuk أَنْتَ)?","ar":null,"explanation":"Buang huruf mudhara'ah: قُومُ → disukunkan menjadi قُومْ. Terjadi iltiqa' sakinain (wawu dan mim), maka wawu dibuang: قُمْ. Tidak perlu hamzah washl karena huruf pertama berharakat.","time":30,"options":["قُمْ","قُومْ","اُقُمْ","قَامْ"],"correct":1,"accepted":[]},{"key":"5757eb51c32804812f3a2c9b48064299","cat":"mashdar","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa mashdar dari عَلَّمَ?","ar":null,"explanation":"عَلَّمَ berwazan فَعَّلَ, mashdarnya تَفْعِيلٌ: تَعْلِيمٌ. عِلْمٌ mashdar عَلِمَ, إِعْلَامٌ mashdar أَعْلَمَ, تَعَلُّمٌ mashdar تَعَلَّمَ.","time":25,"options":["تَعْلِيمٌ","عِلْمٌ","إِعْلَامٌ","تَعَلُّمٌ"],"correct":1,"accepted":[]},{"key":"fa49f9eb6e19b791d6c13dbd88dd5001","cat":"mashdar","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa mashdar dari اِسْتَغْفَرَ?","ar":null,"explanation":"اِسْتَغْفَرَ berwazan اِسْتَفْعَلَ, mashdarnya اِسْتِفْعَالٌ: اِسْتِغْفَارٌ (ta' berharakat kasrah). مُسْتَغْفِرٌ adalah isim fa'il.","time":30,"options":["اِسْتِغْفَارٌ","اِسْتَغْفَارٌ","مُسْتَغْفِرٌ","غُفْرَانٌ"],"correct":1,"accepted":[]},{"key":"8636fcd2cd59fbcf05c55c1f19603298","cat":"isim-fail","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa isim fa'il dari كَتَبَ?","ar":null,"explanation":"Isim fa'il fi'il tsulatsi berwazan فَاعِلٌ: كَاتِبٌ (penulis). مَكْتُوبٌ isim maf'ul, مَكْتَبٌ isim makan.","time":20,"options":["كَاتِبٌ","مَكْتُوبٌ","كِتَابٌ","مَكْتَبٌ"],"correct":1,"accepted":[]},{"key":"654f7f2ae436ef523a4e521e8575716b","cat":"isim-fail","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa isim fa'il dari اِجْتَهَدَ?","ar":null,"explanation":"Isim fa'il dari fi'il lebih dari tiga huruf: ganti huruf mudhara'ah (يَجْتَهِدُ) dengan mim berdhammah dan kasrahkan huruf sebelum akhir: مُجْتَهِدٌ. Jika difathah (مُجْتَهَدٌ) menjadi isim maf'ul.","time":25,"options":["مُجْتَهِدٌ","مُجْتَهَدٌ","جَاهِدٌ","اِجْتِهَادٌ"],"correct":1,"accepted":[]},{"key":"b03eec4b06ba0f1881669adf1b2c235d","cat":"isim-maful","type":"tashrif_battle","level":"beginner","variety":"fusha","prompt":"Apa isim maf'ul dari كَتَبَ?","ar":null,"explanation":"Isim maf'ul fi'il tsulatsi berwazan مَفْعُولٌ: مَكْتُوبٌ (yang ditulis).","time":20,"options":["مَكْتُوبٌ","كَاتِبٌ","مَكْتَبٌ","كِتَابَةٌ"],"correct":1,"accepted":[]},{"key":"bd4b705aaf34dd5bc9cfeb52b108b65e","cat":"isim-maful","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa isim maf'ul dari أَرْسَلَ?","ar":null,"explanation":"Dari mudhari' يُرْسِلُ: ganti huruf mudhara'ah dengan mim berdhammah dan fathahkan huruf sebelum akhir: مُرْسَلٌ (yang diutus). مُرْسِلٌ isim fa'il, إِرْسَالٌ mashdar.","time":30,"options":["مُرْسَلٌ","مُرْسِلٌ","إِرْسَالٌ","رَسُولٌ"],"correct":1,"accepted":[]},{"key":"3fab3251dc05b65b652724758f4af3d0","cat":"tashrif","type":"tashrif_battle","level":"advanced","variety":"fusha","prompt":"Apa bentuk fi'il madhi majhul dari كَتَبَ?","ar":null,"explanation":"Madhi majhul: huruf pertama didhammah dan huruf sebelum akhir dikasrah: كُتِبَ (telah ditulis). يُكْتَبُ adalah mudhari' majhul.","time":30,"options":["كُتِبَ","كَتِبَ","كُتُبَ","يُكْتَبُ"],"correct":1,"accepted":[]},{"key":"775e9471ed7205ca7ebd643def5b502f","cat":"tashrif","type":"tashrif_battle","level":"intermediate","variety":"fusha","prompt":"Apa bentuk fi'il mudhari' majhul dari نَصَرَ untuk dhamir هُوَ?","ar":null,"explanation":"Mudhari' majhul: huruf mudhara'ah didhammah dan huruf sebelum akhir difathah: يُنْصَرُ (ditolong). يَنْصُرُ adalah bentuk ma'lum.","time":25,"options":["يُنْصَرُ","يَنْصُرُ","نُصِرَ","يُنْصِرُ"],"correct":1,"accepted":[]},{"key":"d5cfb472a45eaae614839ea215bc0e4c","cat":"mizan","type":"complete_rule","level":"beginner","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"كَاتِبٌ","explanation":"Huruf asli ك–ت–ب ditimbang dengan ف–ع–ل; alif tambahan setelah huruf pertama tetap ditulis: فَاعِلٌ.","time":20,"options":["فَاعِلٌ","فَعِيلٌ","مَفْعُولٌ","فِعَالٌ"],"correct":1,"accepted":[]},{"key":"b3ed97f6578bd5006c00423598f68ab4","cat":"mizan","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"اِسْتَخْرَجَ","explanation":"Huruf aslinya خ–ر–ج; tambahan اِسْتَـ di depan tetap ditulis: اِسْتَفْعَلَ.","time":25,"options":["اِسْتَفْعَلَ","اِفْتَعَلَ","اِنْفَعَلَ","تَفَاعَلَ"],"correct":1,"accepted":[]},{"key":"db84c05f4886bade80386b2833a7358b","cat":"mizan","type":"complete_rule","level":"advanced","variety":"fusha","prompt":"Apa mizan sharfi (wazan) kata berikut?","ar":"قَالَ","explanation":"قَالَ asalnya قَوَلَ (alif adalah wawu yang berubah, bukan huruf tambahan). Mizan mengikuti huruf asli: فَعَلَ.","time":30,"options":["فَعَلَ","فَاعَلَ","فَالَ","فَعَّلَ"],"correct":1,"accepted":[]},{"key":"3b5961fde5a1ba93fafa023a52738bd8","cat":"mujarrad-mazid","type":"fiil_challenge","level":"beginner","variety":"fusha","prompt":"Apa huruf asli (akar kata) dari kata berikut?","ar":"مَدْرَسَةٌ","explanation":"مَدْرَسَةٌ berasal dari دَرَسَ (belajar). Mim di awal dan ta' marbuthah di akhir adalah huruf tambahan (isim makan berwazan مَفْعَلَةٌ).","time":20,"options":["د – ر – س","م – د – ر","ر – س – ة","م – د – س"],"correct":1,"accepted":[]},{"key":"c4c6c3fda03647256393b1151fe75b62","cat":"mujarrad-mazid","type":"fiil_challenge","level":"intermediate","variety":"fusha","prompt":"Fi'il berikut termasuk …","ar":"تَعَلَّمَ","explanation":"تَعَلَّمَ berwazan تَفَعَّلَ: akar ع–ل–م ditambah dua huruf (ta' di awal dan pengulangan lam/tasydid).","time":25,"options":["Tsulatsi mazid dua huruf","Tsulatsi mujarrad","Tsulatsi mazid satu huruf","Ruba'i mujarrad"],"correct":1,"accepted":[]},{"key":"c00209a127545e070c9bbd5d80ca1e79","cat":"shahih-mutal","type":"fiil_challenge","level":"intermediate","variety":"fusha","prompt":"Fi'il berikut termasuk jenis …","ar":"وَعَدَ","explanation":"Mitsal: fi'il yang huruf pertamanya (fa' fi'il) huruf illat. وَعَدَ diawali wawu.","time":25,"options":["Mu'tal mitsal","Mu'tal ajwaf","Mu'tal naqish","Shahih salim"],"correct":1,"accepted":[]},{"key":"bc89b4cfb32f8c71e24b4e1f9bafe48e","cat":"shahih-mutal","type":"fiil_challenge","level":"intermediate","variety":"fusha","prompt":"Fi'il berikut termasuk jenis …","ar":"رَمَى","explanation":"Naqish: fi'il yang huruf terakhirnya (lam fi'il) huruf illat. رَمَى asalnya رَمَيَ (akhiran ya').","time":25,"options":["Mu'tal naqish","Mu'tal mitsal","Mu'tal ajwaf","Shahih mudha'af"],"correct":1,"accepted":[]},{"key":"fec99521dab3c8abef64bee0c75c8fde","cat":"shahih-mutal","type":"fiil_challenge","level":"advanced","variety":"fusha","prompt":"Fi'il berikut termasuk jenis …","ar":"مَدَّ","explanation":"مَدَّ asalnya مَدَدَ: 'ain dan lam fi'il-nya huruf yang sama, maka disebut mudha'af. Tidak ada huruf illat maupun hamzah, sehingga termasuk shahih.","time":30,"options":["Shahih mudha'af","Mu'tal ajwaf","Shahih mahmuz","Mu'tal lafif"],"correct":1,"accepted":[]},{"key":"9c86d01c9147ad3bcb7f6c12a9341948","cat":"rafa","type":"complete_rule","level":"beginner","variety":"fusha","prompt":"Tanda rafa' yang asli (ashliyyah) adalah …","ar":null,"explanation":"Tanda asli: rafa' = dhammah, nashab = fathah, jarr = kasrah, jazm = sukun. Tanda lain (wawu, alif, ya', dll.) disebut tanda far'iyyah (cabang).","time":20,"options":["Dhammah","Fathah","Kasrah","Sukun"],"correct":1,"accepted":[]},{"key":"6a763906975b4eb0fcde5237a2c7c7d0","cat":"rafa","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"جَاءَ [[الطَّالِبَانِ]]","explanation":"Isim mutsanna di-rafa'-kan dengan alif sebagai pengganti dhammah: الطَّالِبَانِ. Saat manshub/majrur menjadi الطَّالِبَيْنِ.","time":25,"options":["Fa'il marfu' dengan alif karena isim mutsanna","Fa'il marfu' dengan dhammah","Maf'ul bih manshub dengan ya'","Isim majrur dengan ya'"],"correct":1,"accepted":[]},{"key":"42127a0bb9b1a455006c709550316317","cat":"nashab","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"رَأَيْتُ [[أَخَاكَ]]","explanation":"أَخٌ termasuk asma'ul khamsah (أَبٌ، أَخٌ، حَمٌ، فُو، ذُو). Jika di-idhafah-kan kepada selain ya' mutakallim, ia di-nashab-kan dengan alif: أَخَاكَ.","time":25,"options":["Maf'ul bih manshub dengan alif karena asma'ul khamsah","Maf'ul bih manshub dengan fathah","Fa'il marfu' dengan wawu","Isim majrur dengan ya'"],"correct":1,"accepted":[]},{"key":"a53cf31532d4e34871dc2d3b5fbc5539","cat":"nashab","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"لَنْ [[يَذْهَبُوا]]","explanation":"لَنْ me-nashab-kan fi'il mudhari'. يَذْهَبُونَ termasuk af'al khamsah, sehingga tanda nashab-nya membuang nun: لَنْ يَذْهَبُوا.","time":30,"options":["Fi'il mudhari' manshub dengan membuang nun","Fi'il mudhari' majzum dengan membuang nun","Fi'il mudhari' manshub dengan fathah","Fi'il mudhari' marfu' dengan tetapnya nun"],"correct":1,"accepted":[]},{"key":"e41eb41a1094fa8cc516edbe2d8429d4","cat":"jarr","type":"complete_rule","level":"beginner","variety":"fusha","prompt":"Tanda jarr yang asli (ashliyyah) adalah …","ar":null,"explanation":"Tanda jarr yang asli adalah kasrah. Tanda gantinya: ya' (mutsanna, jamak mudzakkar salim, asma'ul khamsah) dan fathah (isim ghairu munsharif).","time":20,"options":["Kasrah","Fathah","Dhammah","Sukun"],"correct":1,"accepted":[]},{"key":"479281bb162e57188ed01aa85f99af14","cat":"jarr","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"سَلَّمْتُ عَلَى [[أَبِيكَ]]","explanation":"أَبٌ termasuk asma'ul khamsah. Setelah huruf jar عَلَى ia majrur, dan tanda jarr-nya ya': أَبِيكَ.","time":25,"options":["Isim majrur dengan ya' karena asma'ul khamsah","Isim majrur dengan kasrah","Maf'ul bih manshub dengan alif","Fa'il marfu' dengan wawu"],"correct":1,"accepted":[]},{"key":"6e8122ffbc2f465124d4cffae30e7220","cat":"jazm","type":"irab_challenge","level":"intermediate","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"لَمْ [[يَكْتُبْ]]","explanation":"لَمْ men-jazm-kan fi'il mudhari'. يَكْتُبُ berakhiran huruf shahih, sehingga tanda jazm-nya sukun: لَمْ يَكْتُبْ.","time":25,"options":["Fi'il mudhari' majzum dengan sukun","Fi'il mudhari' manshub dengan fathah","Fi'il mudhari' marfu' dengan dhammah","Fi'il mudhari' majzum dengan membuang nun"],"correct":1,"accepted":[]},{"key":"5b50ad0e9cf4aee69148248764329db8","cat":"jazm","type":"irab_challenge","level":"advanced","variety":"fusha","prompt":"Tentukan kedudukan dan tanda i'rab kata yang ditandai.","ar":"لَمْ [[يَدْعُ]]","explanation":"يَدْعُو berakhiran huruf illat wawu. Fi'il mudhari' mu'tal akhir di-jazm-kan dengan membuang huruf illat-nya: لَمْ يَدْعُ.","time":30,"options":["Fi'il mudhari' majzum dengan membuang huruf illat (wawu)","Fi'il mudhari' majzum dengan sukun","Fi'il mudhari' marfu' dengan dhammah muqaddarah","Fi'il mudhari' manshub dengan fathah"],"correct":1,"accepted":[]},{"key":"77d9835db934031a912c4693d48155d3","cat":"alamat-irab","type":"complete_rule","level":"intermediate","variety":"fusha","prompt":"Jamak muannats salim ketika manshub ditandai dengan …","ar":null,"explanation":"Jamak muannats salim di-nashab-kan dengan kasrah sebagai pengganti fathah, contoh: رَأَيْتُ الطَّالِبَاتِ.","time":25,"options":["Kasrah","Fathah","Ya'","Alif"],"correct":1,"accepted":[]},{"key":"fc4aae8da0c57029119772cccb26f41b","cat":"alamat-irab","type":"complete_rule","level":"advanced","variety":"fusha","prompt":"Isim ghairu munsharif ketika majrur (tanpa ال dan tidak di-idhafah-kan) ditandai dengan …","ar":null,"explanation":"Isim ghairu munsharif (mamnu' min ash-sharf) di-jarr-kan dengan fathah sebagai pengganti kasrah, contoh: مَرَرْتُ بِأَحْمَدَ. Jika ber-ال atau di-idhafah-kan, kembali memakai kasrah.","time":30,"options":["Fathah","Kasrah","Ya'","Sukun"],"correct":1,"accepted":[]},{"key":"a94a1c190a13a52a2637ba9da0f376c7","cat":"irab-jumlah","type":"sentence_analysis","level":"advanced","variety":"fusha","prompt":"Apa i'rab kata yang ditandai?","ar":"كَانَ الطَّالِبُ [[يَقْرَأُ]] الْكِتَابَ","explanation":"يَقْرَأُ tetap marfu' (tidak didahului 'amil nashab/jazm). Jumlah fi'liyyah يَقْرَأُ الْكِتَابَ berkedudukan nashab sebagai khabar كَانَ (fi mahalli nashbin).","time":30,"options":["Fi'il mudhari' marfu'; jumlahnya menjadi khabar kana (mahall nashab)","Fi'il mudhari' manshub karena كَانَ","Isim kana marfu'","Fi'il madhi mabni 'ala al-fath"],"correct":1,"accepted":[]},{"key":"099e1b573e10a38185fed06e2a706a6d","cat":"irab-jumlah","type":"sentence_analysis","level":"advanced","variety":"fusha","prompt":"Apa i'rab kata yang ditandai?","ar":"[[الطُّلَّابُ]] حَضَرُوا","explanation":"Fa'il tidak didahulukan atas fi'il-nya (pendapat jumhur). Fa'il dari حَضَرُوا adalah wawu jama'ah, sehingga الطُّلَّابُ adalah mubtada', dan jumlah حَضَرُوا menjadi khabarnya.","time":30,"options":["Mubtada' marfu' dengan dhammah","Fa'il marfu' dengan dhammah","Maf'ul bih muqaddam","Khabar muqaddam"],"correct":1,"accepted":[]}]$j$::jsonb) loop
    if not exists (select 1 from categories where slug = q->>'cat') then
      raise exception 'Kategori % tidak ada', q->>'cat';
    end if;
    v_q := null;
    insert into questions (seed_key, category_id, game_type, difficulty, variety, prompt, prompt_ar, explanation, time_limit_sec, is_published)
    select q->>'key', id, (q->>'type')::game_type, (q->>'level')::difficulty, (q->>'variety')::arabic_variety,
           q->>'prompt', q->>'ar', q->>'explanation', (q->>'time')::int, true
    from categories where slug = q->>'cat'
    on conflict (seed_key) do nothing
    returning id into v_q;
    continue when v_q is null;   -- sudah ada
    v_added := v_added + 1;

    for i in 0 .. jsonb_array_length(q->'options') - 1 loop
      insert into answer_options (question_id, label, is_arabic, position)
      values (v_q, q->'options'->>i, (q->'options'->>i) ~ '[\u0600-\u06FF]', i + 1);
    end loop;

    -- correct null = soal susun kalimat (dinilai lewat accepted_texts)
    v_correct := null;
    select id into v_correct from answer_options
    where question_id = v_q and position = (q->>'correct')::int;

    insert into answer_keys (question_id, correct_option_id, accepted_texts)
    values (v_q, v_correct, array(select jsonb_array_elements_text(q->'accepted')));
  end loop;
  raise notice 'Soal baru ditambahkan: %', v_added;
end
$seed$;
